mapper.select:
/* siege_collector.selectMatchBattleLogList */ SELECT b.log_id, b.log_timestamp, b.match_id, b.base_number, b.guild_id, b.wizard_id, b.wizard_name, b.opp_guild_id, b.opp_wizard_id, b.opp_wizard_name, b.win_lose, b.request_type, b.replay_rid_ref, b.battle_desc, b.siege_id, b.match_score_var, b.wizard_level, b.opp_wizard_level, b.log_type_api, b.guild_name, b.opp_guild_name, CASE WHEN b.api_payload IS NOT NULL THEN true ELSE false END AS from_collector FROM battle_log_list b WHERE b.match_id = #{match_id}
AND b.api_payload IS NOT NULL
AND b.base_number = #{base_number}::text
ORDER BY b.log_timestamp DESC LIMIT #{limit} OFFSET #{offset}

/* siege_collector.selectMatchBattleLogCount */
SELECT COUNT(*)::int
  FROM battle_log_list b
 WHERE b.match_id = #{match_id}


   AND b.api_payload IS NOT NULL


   AND b.base_number = #{base_number}::text

/* siege_collector.countGuildAccessToMatch */
SELECT COUNT(*)::int
  FROM guild_siege_battle_log
 WHERE match_id = #{match_id}
   AND guild_id = #{guild_id}::text
 LIMIT 1

/* siege_collector.selectBattleReplayPayload */
SELECT rid,
       payload::text AS payload_json
  FROM siege_battle_replay_payload
 WHERE rid = #{rid}
 LIMIT 1

/* siege_collector.selectLatestApiArchive */ SELECT id, command, siege_id, match_id, captured_at, log_type, base_number, replay_rid, source, payload::text AS payload_json FROM siege_collector_api_archive WHERE command = #{command}
AND match_id = #{match_id}
AND siege_id = #{siege_id}
ORDER BY captured_at DESC LIMIT 1
